-- Original007/010/090/112/141 distinct GitHub registration and immutable archive custody.
-- source_connections remains the separately captured authoritative table from0336, never an alias.
-- Original register_github_source_connection's two-fact effect belongs to the closed live writer;
-- import supplies both original rows in one unit instead of recreating a historical authority fact.
INSERT INTO guard_fail(code) SELECT 'precondition_changed' WHERE EXISTS(SELECT 1 FROM core_authority_activation);
CREATE TABLE github_source_connections (
 source_connection_id TEXT NOT NULL CHECK(length(source_connection_id)=26 AND length(CAST(source_connection_id AS BLOB))=26 AND substr(source_connection_id,1,1) BETWEEN '0' AND '7' AND source_connection_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 organization_id TEXT NOT NULL CHECK(length(organization_id)=26 AND length(CAST(organization_id AS BLOB))=26 AND substr(organization_id,1,1) BETWEEN '0' AND '7' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 project_id TEXT NOT NULL CHECK(length(project_id)=26 AND length(CAST(project_id AS BLOB))=26 AND substr(project_id,1,1) BETWEEN '0' AND '7' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 billing_epoch_id TEXT NOT NULL CHECK(length(billing_epoch_id)=26 AND length(CAST(billing_epoch_id AS BLOB))=26 AND substr(billing_epoch_id,1,1) BETWEEN '0' AND '7' AND billing_epoch_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 provider TEXT NOT NULL CHECK(provider='github'),external_repository_id TEXT NOT NULL CHECK(length(external_repository_id) BETWEEN 1 AND 16 AND substr(external_repository_id,1,1) GLOB '[1-9]' AND external_repository_id NOT GLOB '*[^0-9]*' AND instr(external_repository_id,char(0))=0 AND CAST(external_repository_id AS INTEGER)<=9007199254740991),
 created_at TEXT NOT NULL CHECK((created_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(created_at AS BLOB))=27 AND substr(created_at,1,4) BETWEEN '0001' AND '9999' AND date(substr(created_at,1,10),'+0 days')=substr(created_at,1,10) AND (substr(created_at,12,2)||substr(created_at,15,2)||substr(created_at,18,2)||substr(created_at,21,6)) NOT GLOB '*[^0-9]*' AND substr(created_at,12,2) BETWEEN '00' AND '23' AND substr(created_at,15,2) BETWEEN '00' AND '59' AND substr(created_at,18,2) BETWEEN '00' AND '59') IS TRUE),
 PRIMARY KEY(source_connection_id),
 UNIQUE(organization_id,project_id,billing_epoch_id,source_connection_id,external_repository_id),
 FOREIGN KEY(organization_id,project_id,billing_epoch_id) REFERENCES billing_epochs(organization_id,project_id,billing_epoch_id) ON DELETE RESTRICT
) STRICT, WITHOUT ROWID;
CREATE TRIGGER github_source_connections_no_update BEFORE UPDATE ON github_source_connections BEGIN SELECT RAISE(ABORT,'GitHub source connection is append-only'); END;
CREATE TRIGGER github_source_connections_no_delete BEFORE DELETE ON github_source_connections BEGIN SELECT RAISE(ABORT,'GitHub source connection is append-only'); END;
CREATE TABLE source_archives (
 operation_id TEXT NOT NULL CHECK(length(operation_id)=26 AND length(CAST(operation_id AS BLOB))=26 AND substr(operation_id,1,1) BETWEEN '0' AND '7' AND operation_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 organization_id TEXT NOT NULL CHECK(length(organization_id)=26 AND length(CAST(organization_id AS BLOB))=26 AND substr(organization_id,1,1) BETWEEN '0' AND '7' AND organization_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 project_id TEXT NOT NULL CHECK(length(project_id)=26 AND length(CAST(project_id AS BLOB))=26 AND substr(project_id,1,1) BETWEEN '0' AND '7' AND project_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 billing_epoch_id TEXT NOT NULL CHECK(length(billing_epoch_id)=26 AND length(CAST(billing_epoch_id AS BLOB))=26 AND substr(billing_epoch_id,1,1) BETWEEN '0' AND '7' AND billing_epoch_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 provider TEXT NOT NULL CHECK(provider IN('github','managed')),
 source_connection_id TEXT NOT NULL CHECK(length(source_connection_id)=26 AND length(CAST(source_connection_id AS BLOB))=26 AND substr(source_connection_id,1,1) BETWEEN '0' AND '7' AND source_connection_id NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*'),
 external_repository_id TEXT NOT NULL CHECK((provider='github' AND length(external_repository_id) BETWEEN 1 AND 16 AND substr(external_repository_id,1,1) GLOB '[1-9]' AND external_repository_id NOT GLOB '*[^0-9]*' AND instr(external_repository_id,char(0))=0 AND CAST(external_repository_id AS INTEGER)<=9007199254740991) OR(provider='managed' AND instr(external_repository_id,char(0))=0 AND instr(external_repository_id,'/') BETWEEN 2 AND 129 AND length(external_repository_id)-instr(external_repository_id,'/') BETWEEN 1 AND 128 AND substr(external_repository_id,1,instr(external_repository_id,'/')-1) NOT GLOB '*[^A-Za-z0-9_-]*' AND substr(external_repository_id,instr(external_repository_id,'/')+1) NOT GLOB '*[^A-Za-z0-9_-]*')),
 requested_commit_sha TEXT NOT NULL CHECK(length(requested_commit_sha)=40 AND length(CAST(requested_commit_sha AS BLOB))=40 AND requested_commit_sha NOT GLOB '*[^0-9a-f]*' AND requested_commit_sha<>'0000000000000000000000000000000000000000'),
 resolved_commit_sha TEXT NOT NULL CHECK(resolved_commit_sha=requested_commit_sha),archive_format TEXT NOT NULL CHECK(archive_format='tar.gz'),
 sha256 BLOB NOT NULL CHECK(length(sha256)=32),byte_length INTEGER NOT NULL CHECK(byte_length BETWEEN 1 AND 9007199254740991),
 object_ref TEXT NOT NULL CHECK(instr(object_ref,char(0))=0 AND (
  (length(object_ref)=61 AND substr(object_ref,1,8)='archive_' AND substr(object_ref,9,26)=operation_id AND substr(object_ref,35,1)='_' AND substr(object_ref,36,1) BETWEEN '0' AND '7' AND substr(object_ref,36,26) NOT GLOB '*[^0-9A-HJKMNP-TV-Z]*')
  OR(length(object_ref)<=512 AND substr(object_ref,1,instr(object_ref,'/')-1) IN('r2-version:ohmyho-builds-development','r2-version:ohmyho-builds-production','r2-version:ohmyho-builds-development-eu','r2-version:ohmyho-builds-production-eu') AND instr(object_ref,'#')=length(object_ref)-32 AND instr(object_ref,'#')>instr(object_ref,'/')+1 AND instr(object_ref,'?')=0 AND instr(object_ref,char(9))=0 AND instr(object_ref,char(10))=0 AND instr(object_ref,char(11))=0 AND instr(object_ref,char(12))=0 AND instr(object_ref,char(13))=0 AND instr(object_ref,char(32))=0 AND instr(object_ref,char(133))=0 AND instr(object_ref,char(160))=0 AND instr(object_ref,char(5760))=0 AND instr(object_ref,char(8192))=0 AND instr(object_ref,char(8193))=0 AND instr(object_ref,char(8194))=0 AND instr(object_ref,char(8195))=0 AND instr(object_ref,char(8196))=0 AND instr(object_ref,char(8197))=0 AND instr(object_ref,char(8198))=0 AND instr(object_ref,char(8199))=0 AND instr(object_ref,char(8200))=0 AND instr(object_ref,char(8201))=0 AND instr(object_ref,char(8202))=0 AND instr(object_ref,char(8232))=0 AND instr(object_ref,char(8233))=0 AND instr(object_ref,char(8239))=0 AND instr(object_ref,char(8287))=0 AND instr(object_ref,char(12288))=0 AND substr(object_ref,-32) NOT GLOB '*[^0-9a-f]*'))),
 acquired_at TEXT NOT NULL CHECK((acquired_at GLOB '????-??-??T??:??:??.??????Z' AND length(CAST(acquired_at AS BLOB))=27 AND substr(acquired_at,1,4) BETWEEN '0001' AND '9999' AND date(substr(acquired_at,1,10),'+0 days')=substr(acquired_at,1,10) AND (substr(acquired_at,12,2)||substr(acquired_at,15,2)||substr(acquired_at,18,2)||substr(acquired_at,21,6)) NOT GLOB '*[^0-9]*' AND substr(acquired_at,12,2) BETWEEN '00' AND '23' AND substr(acquired_at,15,2) BETWEEN '00' AND '59' AND substr(acquired_at,18,2) BETWEEN '00' AND '59') IS TRUE),
 PRIMARY KEY(operation_id),
 FOREIGN KEY(organization_id,project_id,operation_id,billing_epoch_id) REFERENCES operations(organization_id,project_id,operation_id,billing_epoch_id) ON DELETE RESTRICT,
 FOREIGN KEY(organization_id,project_id,billing_epoch_id,source_connection_id,external_repository_id) REFERENCES source_connections(organization_id,project_id,billing_epoch_id,source_connection_id,external_repository_id)
) STRICT, WITHOUT ROWID;
CREATE TRIGGER source_archives_no_update BEFORE UPDATE ON source_archives BEGIN SELECT RAISE(ABORT,'Source archive is append-only'); END;
CREATE TRIGGER source_archives_no_delete BEFORE DELETE ON source_archives BEGIN SELECT RAISE(ABORT,'Source archive is append-only'); END;
